        +(k[823]*y[:,82]*y[:,82] - k[824]*y[:,81]*y[:,83])  # R823: CH3S + CH3S -> CH3SH + H2CS
        +(k[831]*y[:,65]*y[:,8] - k[832]*y[:,83]*y[:,3])  # R831: S + CH3 -> H2CS + H
        +(k[833]*y[:,5]*y[:,60] - k[834]*y[:,83]*y[:,3])  # R833: CH + H2S -> H2CS + H
        +(k[835]*y[:,82]*y[:,3] - k[836]*y[:,83]*y[:,1])  # R835: CH3S + H -> H2CS + H2
        +(k[837]*y[:,81]*y[:,76] - k[838]*y[:,83]*y[:,82])  # R837: CH3SH + HCS -> H2CS + CH3S
        -(k[1189]*y[:,83] - k[1190]*y[:,1]*y[:,68])  # R1189: H2CS -> H2 + CS
