        -(k[843]*y[:,84]*y[:,0] - k[844]*y[:,61]*y[:,2])  # R843: CH3CCH + OH -> C3H3 + H2O
        -(k[849]*y[:,84]*y[:,3] - k[850]*y[:,85]*y[:,3])  # R849: CH3CCH + H -> CH2CCH2 + H
