        -(k[845]*y[:,85]*y[:,4] - k[846]*y[:,14]*y[:,17])  # R845: CH2CCH2 + O -> C2H4 + CO
        -(k[847]*y[:,85]*y[:,0] - k[848]*y[:,26]*y[:,8])  # R847: CH2CCH2 + OH -> H2CCO + CH3
        +(k[849]*y[:,84]*y[:,3] - k[850]*y[:,85]*y[:,3])  # R849: CH3CCH + H -> CH2CCH2 + H
