    G[33] = lambda T: np.exp( -(-1*gibbs_sp('H',T)-1*gibbs_sp('C2H5',T)+1*gibbs_sp('C2H4',T)+1*gibbs_sp('H2',T) ) )
    G[35] = lambda T: np.exp( -(-1*gibbs_sp('H',T)-1*gibbs_sp('C2H6',T)+1*gibbs_sp('C2H5',T)+1*gibbs_sp('H2',T) ) )
